import React, { useEffect, useState } from "react";
import axios from "axios";

const UserBlogs = () => {
  const [blogs, setBlogs] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const userId = localStorage.getItem("userId"); // ✅ Lấy userId từ localStorage

  useEffect(() => {
    const fetchUserBlogs = async () => {
      try {
        const token = localStorage.getItem("token");
        
        if (!token) {
          setError("Bạn chưa đăng nhập!");
          setLoading(false);
          return;
        }

        if (!userId) {
          setError("Không tìm thấy ID người dùng.");
          setLoading(false);
          return;
        }

        console.log("🔍 Gửi request với userId:", userId); // ✅ Debug userId

        const res = await axios.get(`http://localhost:9999/getuserblog/${userId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        console.log("✅ API Response:", res.data); // ✅ Debug response

        setBlogs(res.data.blogs || []);
      } catch (err) {
        setError(err.response?.data?.message || "Lỗi khi tải bài viết.");
      } finally {
        setLoading(false);
      }
    };

    fetchUserBlogs();
  }, [userId]);

  if (loading) return <p>Đang tải...</p>;
  if (error) return <p className="text-danger">{error}</p>;

  return (
    <div>
      <h2>Bài viết của bạn</h2>
      {blogs.length > 0 ? (
        blogs.map((blog) => <p key={blog._id}>{blog.title}</p>)
      ) : (
        <p>Chưa có bài viết nào.</p>
      )}
    </div>
  );
};

export default UserBlogs;
